"""D batch 53: Johnson's division from R481 Johnson, R482 Steuart, R483 Williams (Nicholls' brigade), R488 Walker (Stonewall) and R489-R494 (its regiments), R495 J. M. Jones, R496-R503 (Jones' brigade and regiments), R505 Andrews (artillery battalion; R504 Latimer is Winchester only)."""
from positions_build import C

JD = 'cs-2c-johnson'
ST = 'cs-2c-johnson-steuart'
